// Tiny schedule parser (UTC).
//   cron:      '*/15 * * * *', '0 9 * * 1-5', '@hourly', '@daily', '@weekly', '@monthly'
//   interval:  'every 30s', 'every 5m', 'every 2h', 'every 1d'

const SHORTCUTS = { '@hourly': '0 * * * *', '@daily': '0 0 * * *', '@weekly': '0 0 * * 0', '@monthly': '0 0 1 * *' };
const RANGES = [[0, 59], [0, 23], [1, 31], [1, 12], [0, 6]];
const UNITS = { s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 };

export const parseDuration = (text) => {
  if (typeof text === 'number') return text;
  const m = /^(\d+)\s*(s|m|h|d)$/.exec(String(text).trim());
  if (!m) throw new Error(`Invalid duration "${text}" (use e.g. 30s, 5m, 2h, 1d)`);
  return Number(m[1]) * UNITS[m[2]];
};

function parseField(field, [min, max]) {
  const values = new Set();
  for (const part of field.split(',')) {
    const [range, stepText] = part.split('/');
    const step = stepText ? Number(stepText) : 1;
    const [lo, upper] = range === '*' ? [min, max] : range.split('-').map(Number);
    const hi = upper ?? (stepText ? max : lo);
    if (![lo, hi, step].every(Number.isInteger) || lo < min || hi > max || lo > hi || step < 1) throw new Error(`Invalid cron field "${field}"`);
    for (let v = lo; v <= hi; v += step) values.add(v);
  }
  return values;
}

export function parseSchedule(expr) {
  const text = String(expr).trim();
  if (text.startsWith('every ')) return { kind: 'interval', ms: parseDuration(text.slice(6)) };
  const fields = (SHORTCUTS[text] ?? text).split(/\s+/);
  if (fields.length !== 5) throw new Error(`Invalid cron "${expr}": expected 5 fields`);
  const [minute, hour, dom, month, dow] = fields.map((f, i) => parseField(f.replace(/^7$/, '0'), RANGES[i]));
  return { kind: 'cron', minute, hour, dom, month, dow, domAny: fields[2] === '*', dowAny: fields[4] === '*' };
}

/** Next run strictly after `from`. */
export function nextRun(schedule, from = new Date()) {
  if (schedule.kind === 'interval') return new Date(from.getTime() + schedule.ms);
  const d = new Date(from.getTime());
  d.setUTCSeconds(0, 0);
  d.setUTCMinutes(d.getUTCMinutes() + 1);
  for (let i = 0; i < 366 * 24 * 60; i++) {
    const dayOk = schedule.domAny && schedule.dowAny
      ? true
      : schedule.domAny
        ? schedule.dow.has(d.getUTCDay())
        : schedule.dowAny
          ? schedule.dom.has(d.getUTCDate())
          : schedule.dom.has(d.getUTCDate()) || schedule.dow.has(d.getUTCDay());
    if (!schedule.month.has(d.getUTCMonth() + 1) || !dayOk) {
      d.setUTCDate(d.getUTCDate() + 1);
      d.setUTCHours(0, 0, 0, 0);
      continue;
    }
    if (!schedule.hour.has(d.getUTCHours())) {
      d.setUTCHours(d.getUTCHours() + 1, 0, 0, 0);
      continue;
    }
    if (schedule.minute.has(d.getUTCMinutes())) return d;
    d.setUTCMinutes(d.getUTCMinutes() + 1);
  }
  throw new Error('Schedule never matches');
}

import { existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { definePlugin, notFound, badRequest } from '#calm';
import { createQueue } from './queue.js';

/** Declare a job in app/jobs/<name>.js */
export const defineJob = (def) => ({ kind: 'calm.job', ...def });

export default definePlugin({
  name: 'jobs',
  env: {
    JOBS_WORKER: 'Set to "off" on instances that should not run jobs',
    JOBS_CONCURRENCY: 'Jobs run at the same time per instance (default 4)',
  },
  async setup(calm) {
    const queue = createQueue(calm.app, { concurrency: Number(process.env.JOBS_CONCURRENCY || 4) });
    calm.provide('jobs', queue);

    const dir = join(calm.app.root, 'app', 'jobs');
    if (existsSync(dir)) {
      for (const file of readdirSync(dir).filter((f) => f.endsWith('.js')).sort()) {
        const def = (await import(pathToFileURL(join(dir, file)).href)).default;
        if (def?.kind !== 'calm.job') throw new Error(`app/jobs/${file} must "export default defineJob({ ... })"`);
        queue.define(def);
      }
    }

    const workerOn = process.env.JOBS_WORKER !== 'off' && calm.config.mode !== 'test';
    if (workerOn) {
      calm.onStart(() => queue.start());
      calm.onShutdown(() => queue.stop());
    }

    calm.routes(
      (r) => {
        r.get('/', { policy: 'admin', summary: 'List jobs', tags: ['jobs'] }, async (ctx) => {
          const filter = {};
          if (ctx.query.status) filter.status = String(ctx.query.status);
          if (ctx.query.name) filter.name = String(ctx.query.name);
          const limit = Math.min(Number(ctx.query.limit) || 50, 200);
          const jobs = await queue.Job.find(filter).sort({ updatedAt: -1 }).limit(limit).lean();
          return jobs.map(view);
        });
        r.get('/stats', { policy: 'admin', summary: 'Job counts by name and status', tags: ['jobs'] }, () => queue.stats());
        r.post('/:jobId/retry', { policy: 'admin', summary: 'Retry a failed job', tags: ['jobs'] }, async (ctx) => {
          const job = await queue.retry(ctx.params.jobId).catch(() => null);
          if (!job) throw notFound('No failed job with that id');
          return view(job);
        });
        r.post('/enqueue', { policy: 'admin', summary: 'Queue a job by name', tags: ['jobs'] }, async (ctx) => {
          const { name, data } = ctx.req.body ?? {};
          if (typeof name !== 'string') throw badRequest('name is required');
          return view(await queue.enqueue(name, data ?? {}));
        });
      },
      { prefix: '/jobs' },
    );

    calm.devtools.panel('jobs', async () => {
      const stats = await queue.stats();
      const recent = await queue.Job.find().sort({ updatedAt: -1 }).limit(25).lean();
      return { ...stats, recent: recent.map(view) };
    });

    calm.doctor(() =>
      process.env.JOBS_WORKER === 'off'
        ? [{ level: 'info', id: 'jobs-worker-off', title: 'Jobs worker is off on this instance', detail: 'JOBS_WORKER=off: make sure another process runs with JOBS_WORKER=on.' }]
        : [],
    );
  },
});

const view = (j) => ({
  id: String(j._id),
  name: j.name,
  status: j.status,
  attempts: j.attempts,
  maxAttempts: j.maxAttempts,
  runAt: j.runAt,
  finishedAt: j.finishedAt ?? null,
  lastError: j.lastError ? j.lastError.split('\n')[0] : null,
  scheduled: Boolean(j.uniqueKey?.startsWith('schedule:')),
});

import { hostname } from 'node:os';
import { randomUUID } from 'node:crypto';
import { parseSchedule, nextRun, parseDuration } from './cron.js';

// A job queue stored in MongoDB (collection calm_jobs). Workers claim jobs atomically
// with findOneAndUpdate, so you can run as many instances as you like.

export function createQueue(app, { concurrency = 4, pollMs = 1000, lockTimeoutMs = 5 * 60_000, keepCompletedDays = 7 } = {}) {
  const { Schema } = app.mongoose;
  const schema = new Schema(
    {
      name: { type: String, required: true },
      data: { type: Schema.Types.Mixed, default: {} },
      status: { type: String, enum: ['queued', 'running', 'completed', 'failed'], default: 'queued' },
      runAt: { type: Date, default: () => new Date() },
      attempts: { type: Number, default: 0 },
      maxAttempts: { type: Number, default: 3 },
      lockedAt: Date,
      lockedBy: String,
      lastError: String,
      finishedAt: Date,
      uniqueKey: String,
      result: Schema.Types.Mixed,
    },
    { collection: 'calm_jobs', timestamps: true, versionKey: false },
  );
  schema.index({ status: 1, runAt: 1 });
  schema.index({ name: 1, status: 1 });
  schema.index({ uniqueKey: 1 }, { unique: true, partialFilterExpression: { uniqueKey: { $type: 'string' } } });
  schema.index({ finishedAt: 1 }, { expireAfterSeconds: keepCompletedDays * 86_400, partialFilterExpression: { status: 'completed' } });
  const Job = app.mongoose.model('calmJob', schema);

  const definitions = new Map();
  const workerId = `${hostname()}:${process.pid}:${randomUUID().slice(0, 8)}`;
  let running = 0;
  let timer = null;
  let stopping = false;
  let ticks = 0;
  const inflight = new Set();

  const api = {
    Job,
    /** Register a job handler. */
    define(def) {
      if (!def?.name || typeof def.run !== 'function') throw new Error('defineJob({ name, run }) needs a name and a run function');
      if (definitions.has(def.name)) throw new Error(`Job "${def.name}" is defined twice`);
      const full = { retries: 3, backoff: '10s', ...def, scheduleParsed: def.schedule ? parseSchedule(def.schedule) : null };
      definitions.set(def.name, full);
      if (def.on) app.events.on(def.on, (payload) => api.enqueue(def.name, payload));
      return full;
    },

    /** Queue a job. opts: { delay: '5m' | ms, runAt: Date, uniqueKey, retries } */
    async enqueue(name, data = {}, opts = {}) {
      const def = definitions.get(name);
      if (!def) throw new Error(`Unknown job "${name}". Known: ${[...definitions.keys()].join(', ')}`);
      const runAt = opts.runAt ?? new Date(Date.now() + (opts.delay ? parseDuration(opts.delay) : 0));
      const doc = { name, data, runAt, maxAttempts: (opts.retries ?? def.retries) + 1, ...(opts.uniqueKey ? { uniqueKey: opts.uniqueKey } : {}) };
      try {
        return (await Job.create(doc)).toObject();
      } catch (err) {
        if (err.code === 11000 && opts.uniqueKey) return Job.findOne({ uniqueKey: opts.uniqueKey }).lean();
        throw err;
      }
    },

    async stats() {
      const rows = await Job.aggregate([{ $group: { _id: { name: '$name', status: '$status' }, count: { $sum: 1 } } }]);
      const byName = {};
      for (const { _id, count } of rows) (byName[_id.name] ??= { queued: 0, running: 0, completed: 0, failed: 0 })[_id.status] = count;
      return {
        worker: timer ? workerId : 'off',
        running,
        definitions: [...definitions.values()].map((d) => ({ name: d.name, schedule: d.schedule ?? null, on: d.on ?? null, retries: d.retries })),
        byName,
      };
    },

    async retry(id) {
      const res = await Job.findOneAndUpdate({ _id: id, status: 'failed' }, { $set: { status: 'queued', runAt: new Date(), attempts: 0 }, $unset: { lastError: 1, finishedAt: 1 } }, { returnDocument: 'after' }).lean();
      return res;
    },

    /** Process everything that is due right now (tests and scripts). */
    async drain() {
      for (let i = 0; i < 1000; i++) {
        const claimed = await claim();
        if (!claimed) break;
        await execute(claimed);
      }
      await Promise.all([...inflight]);
    },

    async start() {
      for (const def of definitions.values()) if (def.scheduleParsed) await ensureScheduled(def);
      stopping = false;
      timer = setInterval(() => tick().catch((err) => app.log.error('Job worker tick failed', { err })), pollMs);
      timer.unref();
      app.log.info(`Jobs worker started (${definitions.size} jobs, concurrency ${concurrency})`);
    },

    async stop() {
      stopping = true;
      if (timer) clearInterval(timer);
      timer = null;
      await Promise.race([Promise.all([...inflight]), new Promise((r) => setTimeout(r, 10_000))]);
    },
  };

  async function ensureScheduled(def) {
    await Job.updateOne(
      { uniqueKey: `schedule:${def.name}` },
      { $setOnInsert: { name: def.name, data: {}, status: 'queued', runAt: nextRun(def.scheduleParsed), attempts: 0, maxAttempts: def.retries + 1 } },
      { upsert: true },
    );
  }

  const claim = () =>
    Job.findOneAndUpdate(
      { status: 'queued', runAt: { $lte: new Date() }, name: { $in: [...definitions.keys()] } },
      { $set: { status: 'running', lockedAt: new Date(), lockedBy: workerId }, $inc: { attempts: 1 } },
      { sort: { runAt: 1 }, returnDocument: 'after' },
    ).lean();

  async function tick() {
    if (++ticks % 30 === 0) {
      // Recover jobs whose worker died mid-run.
      await Job.updateMany({ status: 'running', lockedAt: { $lt: new Date(Date.now() - lockTimeoutMs) } }, { $set: { status: 'queued' } });
    }
    while (!stopping && running < concurrency) {
      const job = await claim();
      if (!job) break;
      running++;
      const p = execute(job).finally(() => {
        running--;
        inflight.delete(p);
      });
      inflight.add(p);
    }
  }

  async function execute(job) {
    const def = definitions.get(job.name);
    const log = app.log;
    const started = Date.now();
    try {
      const result = await def.run(job.data, { app, job, log });
      if (def.scheduleParsed) {
        await Job.updateOne({ _id: job._id }, { $set: { status: 'queued', runAt: nextRun(def.scheduleParsed), attempts: 0, result: result ?? null }, $unset: { lockedAt: 1, lockedBy: 1, lastError: 1 } });
      } else {
        await Job.updateOne({ _id: job._id }, { $set: { status: 'completed', finishedAt: new Date(), result: result ?? null }, $unset: { lockedAt: 1, lockedBy: 1 } });
      }
      app.events.emit('job.completed', { id: String(job._id), name: job.name, ms: Date.now() - started });
    } catch (err) {
      const message = String(err?.stack ?? err).slice(0, 4000);
      if (job.attempts < job.maxAttempts) {
        const wait = parseDuration(def.backoff) * 2 ** (job.attempts - 1);
        await Job.updateOne({ _id: job._id }, { $set: { status: 'queued', runAt: new Date(Date.now() + Math.min(wait, 3_600_000)), lastError: message }, $unset: { lockedAt: 1, lockedBy: 1 } });
        log.warn(`Job ${job.name} failed (attempt ${job.attempts}/${job.maxAttempts}), retrying`, { err: err?.message });
      } else if (def.scheduleParsed) {
        await Job.updateOne({ _id: job._id }, { $set: { status: 'queued', runAt: nextRun(def.scheduleParsed), attempts: 0, lastError: message }, $unset: { lockedAt: 1, lockedBy: 1 } });
        log.error(`Scheduled job ${job.name} failed, will run again at its next time`, { err: err?.message });
      } else {
        await Job.updateOne({ _id: job._id }, { $set: { status: 'failed', finishedAt: new Date(), lastError: message }, $unset: { lockedAt: 1, lockedBy: 1 } });
        log.error(`Job ${job.name} failed permanently`, { err: err?.message });
        app.events.emit('job.failed', { id: String(job._id), name: job.name, error: err?.message });
      }
    }
  }

  return api;
}

import { defineJob } from '#app/blocks/jobs/index.js';

// Example job: runs in the background whenever someone signs up.
// Other triggers: schedule: '0 9 * * 1-5' (cron, UTC) or schedule: 'every 10m',
// or enqueue manually: ctx.app.ext.jobs.enqueue('welcome-email', { user })
export default defineJob({
  name: 'welcome-email',
  on: 'auth.registered',
  retries: 3,
  async run({ user }, { app }) {
    await app.mailer.send({
      to: user.email,
      subject: `Welcome to ${app.config.app.name}`,
      text: `Hi ${user.name},\n\nYour account is ready. Happy building!`,
    });
  },
});
